const input = $json || {};
const update = input.update || {};

const chatId =
  input.chatId ||
  update.chatId ||
  update.message?.chat?.id ||
  update.callback_query?.message?.chat?.id;

const callbackQueryId =
  input.callbackQueryId ||
  update.callback_query?.id ||
  null;

const msg = String(
  input.msg ??
  update.text ??
  update.message?.text ??
  update.callback_query?.data ??
  ""
).trim();

let savedSession = input.session || null;
if (typeof savedSession === "string") {
  try { savedSession = JSON.parse(savedSession); } catch { savedSession = null; }
}

let s = savedSession || {
  step: "MAIN_MENU",
  requestType: "",
  temp: {},
  aiSearch: {},
  language: "en"
};

s.temp = s.temp || {};
s.aiSearch = s.aiSearch || {};
s.language = "en";

