function response(text, replyMarkup) {
  return [{ json: { chatId, text, replyMarkup, session: s, callbackQueryId } }];
}

function responseAI(aiPrompt, replyMarkup) {
  return [{ json: { chatId, useAI: true, aiPrompt, replyMarkup, session: s, callbackQueryId } }];
}

function mainMenuMarkup() {
  return {
    inline_keyboard: [
      [{ text: "🤖 Smart Property Advisor", callback_data: "smart_advisor" }],
      [{ text: "📤 Submit a Property", callback_data: "sell_request" }],
      [{ text: "📩 Request Advisor Contact", callback_data: "consult_request" }],
      [{ text: "❓ FAQ", callback_data: "faq" }],
      [{ text: "ℹ️ About This Demo", callback_data: "about_demo" }]
    ]
  };
}

function backMarkup() {
  return { inline_keyboard: [[{ text: "🏠 Main Menu", callback_data: "back_to_main" }]] };
}

function advisorMarkup() {
  return {
    inline_keyboard: [
      [{ text: "📩 Request Advisor Contact", callback_data: "consult_request" }],
      [{ text: "🔄 Start New Property Search", callback_data: "smart_advisor" }],
