      [{ text: "✅ Submit Demo Request", callback_data: "confirm_request" }],
      [{ text: "✏️ Edit Information", callback_data: "edit_request" }],
      [{ text: "❌ Cancel", callback_data: "cancel_request" }]
    ]
  };
}

function faqMarkup() {
  return {
    inline_keyboard: [
      [{ text: "Rental documents", callback_data: "faq_documents" }],
      [{ text: "What is Kaution?", callback_data: "faq_kaution" }],
      [{ text: "What is SCHUFA?", callback_data: "faq_schufa" }],
      [{ text: "Can foreigners buy property?", callback_data: "faq_buy_foreigner" }],
      [{ text: "Request advisor contact", callback_data: "faq_consult" }],
      [{ text: "🏠 Main Menu", callback_data: "back_to_main" }]
    ]
  };
}

function normalizeText(text) {
  return String(text || "").toLowerCase().replace(/\s+/g, " ").trim();
}

function detectDealType(text) {
  const t = normalizeText(text);
  if (/(buy|purchase|investment|for sale)/.test(t)) return "buy";
  if (/(rent|rental|lease)/.test(t)) return "rent";
  return "";
}

function detectCity(text) {
  const t = normalizeText(text);
  const cities = ["berlin", "hamburg", "munich", "frankfurt", "düsseldorf", "dusseldorf"];
  const found = cities.find(c => t.includes(c));
  if (!found) return "";
  return found === "dusseldorf" ? "düsseldorf" : found;
}

function detectBudget(text) {
  const t = String(text || "").replace(/,/g, "");
  const nums = t.match(/\d{3,7}/g);
  if (!nums) return "";
  return Number(nums[0]);
}

function detectPropertyType(text) {
  const t = normalizeText(text);
  if (t.includes("private room") || /\broom\b/.test(t)) return "Private room";
  if (t.includes("studio")) return "Studio";
  if (/(one-bedroom|1 bedroom|one bedroom)/.test(t)) return "One-bedroom apartment";
  if (/(two-bedroom|2 bedroom|two bedroom)/.test(t)) return "Two-bedroom apartment";
  if (/(three-bedroom|3 bedroom|three bedroom|family apartment)/.test(t)) return "Three-bedroom apartment";
  if (t.includes("apartment") || t.includes("flat")) return "Apartment";
  return "";
}

function detectPeopleCount(text) {
  const m = String(text || "").match(/(\d+)\s*(people|persons|person|adults?)/i);
  return m ? m[1] : "";
}

function isGeneralQuestion(text) {
  const t = normalizeText(text);
  const keywords = [
    "what is", "what does", "difference", "schufa", "kaution",
    "warmmiete", "kaltmiete", "anmeldung", "documents", "contract", "guarantor"
  ];
  return keywords.some(k => t.includes(k));
}

function updateAiSearchFromText(text) {
  const dealType = detectDealType(text);
  const city = detectCity(text);
  const budget = detectBudget(text);
  const propertyType = detectPropertyType(text);
  const peopleCount = detectPeopleCount(text);

  if (dealType) s.aiSearch.dealType = dealType;
  if (city) s.aiSearch.city = city;
  if (budget) s.aiSearch.budget = budget;
  if (propertyType) s.aiSearch.propertyType = propertyType;
  if (peopleCount) s.aiSearch.peopleCount = peopleCount;

  s.aiSearch.rawMessages = s.aiSearch.rawMessages || [];
  s.aiSearch.rawMessages.push(text);
}

function nextMissingQuestion() {
  if (!s.aiSearch.dealType) return "Are you looking to rent or buy?";
  if (!s.aiSearch.city) return "Which city are you interested in? For example, Berlin or Hamburg.";
  if (!s.aiSearch.budget) return "What budget do you have in mind?";
  if (!s.aiSearch.propertyType) return "What type of property are you looking for? Room, studio, or apartment?";
  return null;
}

function propertyText(p) {
  const priceLabel = p.dealType === "buy"
    ? `€${p.price.toLocaleString("en-US")}`
    : `€${p.price.toLocaleString("en-US")} / month`;

  return `ID: ${p.id}
Title: ${p.title}
City: ${p.city}
District: ${p.district}
Type: ${p.propertyType}
Size: ${p.size}
Rooms: ${p.rooms}
Price: ${priceLabel}
Deposit: ${p.deposit}
Suitable for: ${p.suitableFor}
Features: ${p.features.join(", ")}
Description: ${p.description}
Availability: ${p.availability}
Demo link: ${p.link}`;
}

function searchBestProperties() {
  const need = s.aiSearch || {};

  const scored = PROPERTIES.map(p => {
    let score = 0;
    const reasons = [];

    if (need.dealType && p.dealType === need.dealType) {
      score += 8; reasons.push("Matches the requested deal type");
    }

    if (need.city && normalizeText(p.city) === need.city) {
      score += 8; reasons.push("Located in the requested city");
    }

    if (need.propertyType &&
      (p.propertyType === need.propertyType ||
      (need.propertyType === "Apartment" && p.propertyType.includes("apartment")))) {
      score += 6; reasons.push("Property type is close to the request");
    }

    if (need.budget) {
      if (p.price <= need.budget) {
        score += 6; reasons.push("Within the stated budget");
      } else if (p.price <= need.budget * 1.2) {
        score += 3; reasons.push("Slightly above budget");
      }
    }

    if (need.peopleCount) {
      const people = Number(need.peopleCount);
      if (people >= 3 && p.propertyType.includes("Three-bedroom")) {
        score += 3; reasons.push("Better suited to a larger household");
      }
      if (people <= 2 && ["One-bedroom apartment", "Studio", "Private room"].includes(p.propertyType)) {
        score += 3; reasons.push("Better suited to one or two people");
      }
    }

    return { property: p, score, reasons };
  }).sort((a, b) => b.score - a.score);

  const best = scored.filter(x => x.score > 0).slice(0, 3);
  if (best.length) return best;

  return scored.slice(0, 3).map(x => ({
    ...x,
    reasons: ["No exact match was found; this is one of the closest demo options"]
  }));
}

function buildPropertySuggestionPrompt(matches) {
  const need = s.aiSearch || {};
  const exactEnough = matches[0]?.score >= 18;

  return `
You are an initial real estate advisor for people looking for property in Germany.

User requirements:
Deal type: ${need.dealType || "unknown"}
City: ${need.city || "unknown"}
Budget: ${need.budget || "unknown"}
Property type: ${need.propertyType || "unknown"}
People: ${need.peopleCount || "unknown"}

Search result:
${exactEnough ? "A few reasonably close options were found." : "No exact match was found, so the closest demo options were selected."}

Allowed property options:
${matches.map((m, i) => `
Option ${i + 1}
${propertyText(m.property)}
Reasons: ${m.reasons.join(", ")}
Match score: ${m.score}
`).join("\n---\n")}

Rules:
- Recommend only from the options above.
- Do not invent properties, prices, availability, or links.
- If there is no exact match, say so clearly.
- Keep the answer concise, practical, and professional.
- End by mentioning that the user can request advisor contact from the menu.
- Make clear that these are demo listings for initial evaluation only.
- Output only the message text.
`;
}

function buildInterruptionPrompt(userMessage, nextQuestion) {
  return `
You are an initial real estate advisor for Germany.

The user asked this question during the property search:
"${userMessage}"

Current property search context:
${JSON.stringify(s.aiSearch, null, 2)}

After answering briefly, return the user to the previous search flow and ask:
"${nextQuestion}"

Rules:
- Answer the question briefly and clearly.
- Do not give definitive legal, tax, immigration, or financial advice.
- Do not invent properties or prices.
- Keep the tone professional and helpful.
- Output only the message text.
`;
}

function buildGeneralAdvicePrompt(userMessage) {
  return `
You are an initial real estate advisor for Germany.

User message:
"${userMessage}"

Rules:
- Give only general real-estate guidance.
- Do not provide definitive legal, tax, immigration, or investment advice.
- If the user is looking for a property, guide them to the Smart Property Advisor.
- Do not invent listings, prices, or links.
- Keep the response concise and professional.
- Mention that this is a demo for initial guidance.
- Output only the message text.
`;
}

function generateRequestCode() {
  return `DEMO-${Math.floor(1000 + Math.random() * 9000)}`;
}

function startRequest(type) {
  s.step = "REQ_NAME";
  s.requestType = type;
  s.temp = {};

  const title = type === "Property Submission"
    ? `📤 Property Submission

In a real implementation, an owner or agent could submit initial property details for review.`
    : `📩 Advisor Contact Request

Please provide a few details so the request can be reviewed.`;

  return response(`${title}

Enter your full name:`, backMarkup());
}

function requestReviewText() {
  return `Please review the request:

Request type:
${s.requestType || "-"}

Name:
${s.temp.name || "-"}

Phone / WhatsApp:
${s.temp.phone || "-"}

City / Area:
${s.temp.city || "-"}

Budget / Financial note:
${s.temp.budget || "-"}

Notes:
${s.temp.notes || "-"}

File:
${s.temp.fileStatus || "No file"}

If everything is correct, submit the request.`;
}

if (!chatId) {
  return [{ json: { chatId: "", text: "Error: chatId was not received.", session: s, callbackQueryId } }];
}

if (["/start", "start", "hello", "hi", "back_to_main"].includes(msg.toLowerCase())) {
  s.step = "MAIN_MENU";
  s.requestType = "";
  s.temp = {};
  s.aiSearch = {};

  return response(
    `Welcome to the Real Estate AI Advisor Demo 👋

This workflow demonstrates initial property qualification, smart property matching, FAQ handling, and lead collection.

All listings and data in this public version are demo data.

Choose an option below:`,
    mainMenuMarkup()
  );
}

if (msg === "smart_advisor") {
  s.step = "WAITING_SMART_ADVISOR";
  s.aiSearch = {};

  return response(
    `🤖 Smart Property Advisor

Describe what you are looking for in a natural sentence.

Examples:
I need an apartment to rent in Berlin.
I am looking for a student studio in Hamburg.
I want to buy an apartment in Berlin for around €350,000.

The recommendations in this demo are based only on sample listing data.`,
    backMarkup()
  );
}

if (s.step === "WAITING_SMART_ADVISOR") {
  updateAiSearchFromText(msg);
  const nextQuestion = nextMissingQuestion();

  if (isGeneralQuestion(msg) && nextQuestion) {
    return responseAI(buildInterruptionPrompt(msg, nextQuestion), backMarkup());
  }

  if (nextQuestion) return response(nextQuestion, backMarkup());

  const matches = searchBestProperties();
  s.step = "MAIN_MENU";
  return responseAI(buildPropertySuggestionPrompt(matches), advisorMarkup());
}

if (msg === "sell_request") return startRequest("Property Submission");
if (msg === "consult_request") return startRequest("Advisor Contact");

if (msg === "about_demo") {
  return response(
    `ℹ️ About This Demo

This workflow demonstrates:

- Initial real-estate inquiry handling
- Smart requirement collection
- Matching users with demo property data
- FAQ responses
- Lead collection
- Session persistence

In a real implementation, the workflow can connect to a CRM, Google Sheets, property database, website, or internal system.`,
    mainMenuMarkup()
  );
}

if (msg === "faq") return response("❓ Choose a question:", faqMarkup());

const FAQ = {
  faq_documents:
    "For a rental application in Germany, landlords may ask for identification, proof of income, employment documents, SCHUFA, and other supporting documents. Requirements vary by landlord and property.",
  faq_kaution:
    "Kaution is the rental security deposit. In many cases it can be up to three months of the base rent and may be returned at the end of the tenancy if there are no outstanding obligations or damages.",
  faq_schufa:
    "SCHUFA is a credit-information report commonly requested in Germany. New arrivals may sometimes need alternative documentation depending on the landlord.",
  faq_buy_foreigner:
    "Foreign nationals can generally purchase property in Germany, but financing, taxes, contracts, and legal review should be discussed with qualified professionals.",
  faq_consult:
    "Choose “Request Advisor Contact” from the main menu and enter your contact details, preferred city, budget, and notes."
};

if (FAQ[msg]) {
  return response(
    `${FAQ[msg]}

This is general introductory information and not definitive legal or financial advice.`,
    faqMarkup()
  );
}

if (s.step === "REQ_NAME") {
  s.temp.name = msg;
  s.step = "REQ_PHONE";
  return response("Enter your phone or WhatsApp number:", backMarkup());
}

if (s.step === "REQ_PHONE") {
  s.temp.phone = msg;
  s.step = "REQ_CITY";
  return response("Enter the city or area in Germany you are interested in:", backMarkup());
}

if (s.step === "REQ_CITY") {
  s.temp.city = msg;
  s.step = "REQ_BUDGET";
  return response(
    s.requestType === "Property Submission"
      ? "Enter the approximate property price or a short financial note:"
      : "Enter your approximate budget:",
    backMarkup()
  );
}

if (s.step === "REQ_BUDGET") {
  s.temp.budget = msg;
  s.step = "REQ_NOTES";
  return response("Add any notes. If none, type: none", backMarkup());
}

if (s.step === "REQ_NOTES") {
  s.temp.notes = msg;
  s.step = "REQ_FILE_OPTION";

  return response(
    `In a real implementation, users could also upload files or documents.

Choose how to continue:`,
    fileOptionMarkup()
  );
}

if (s.step === "REQ_FILE_OPTION" && msg === "file_demo") {
  s.temp.fileStatus = "User indicated that a file is available.";
  s.step = "REQ_CONFIRM";
  return response(requestReviewText(), confirmRequestMarkup());
}

if (s.step === "REQ_FILE_OPTION" && msg === "no_file") {
  s.temp.fileStatus = "No file";
  s.step = "REQ_CONFIRM";
  return response(requestReviewText(), confirmRequestMarkup());
}

if (msg === "confirm_request") {
  const code = generateRequestCode();

  s.step = "MAIN_MENU";
  s.requestType = "";
  s.temp = {};

  return response(
    `✅ Demo request submitted.

Demo reference:
${code}

In a real implementation, this data could be stored in a CRM, Google Sheet, or internal lead-management system.`,
    mainMenuMarkup()
  );
}

if (msg === "edit_request") {
  s.step = "REQ_NAME";
  s.temp = {};
  return response("Let's update the information. Enter your full name:", backMarkup());
}

if (msg === "cancel_request") {
  s.step = "MAIN_MENU";
  s.requestType = "";
  s.temp = {};
  return response("Request cancelled.", mainMenuMarkup());
}

if (msg.length > 12) {
  return responseAI(buildGeneralAdvicePrompt(msg), mainMenuMarkup());
}

return response(
  `I didn't understand that message.

Please use the menu or open the Smart Property Advisor and describe what you are looking for.`,
  mainMenuMarkup()
);

const aiText =
  $json.text ||
  $json.output ||
  $json.response ||
  $json.result ||
  $json.message ||
  $json.data ||
  "";

const original = $('Real Estate Advisor Logic').first().json;

return [{
  json: {
    chatId: original.chatId,
    text: String(aiText || "Sorry, I couldn't generate an advisor response right now. Please try again.").trim(),
    replyMarkup: original.replyMarkup,
    session: original.session,
    callbackQueryId: original.callbackQueryId
  }
}];

const update = $json || {};
const raw = update.body || update.data || update;

const chatId =
  raw.chatId ||
  raw.chat_id ||
  raw.message?.chat?.id ||
  raw.callback_query?.message?.chat?.id ||
  raw.callback_query?.from?.id ||
  raw.from?.id ||
  null;

const callbackQueryId =
  raw.callback_query?.id ||
  null;

let msg = String(
  raw.text ??
  raw.message?.text ??
  raw.message?.caption ??
  raw.callback_query?.data ??
  ""
).trim();

if (!msg && chatId) msg = "/start";
if (msg === "Start" || msg === "start") msg = "/start";

return [{
  json: {
    update: raw,
    chatId,
    userKey: chatId ? String(chatId) : "",
    msg,
    callbackQueryId
  }
}];

const normalized = $('Normalize Telegram Input').first().json;
const row = $json || {};

let savedSession = row.session || null;

if (typeof savedSession === "string") {
  try { savedSession = JSON.parse(savedSession); } catch { savedSession = null; }
}

return [{
  json: {
    update: normalized.update,
    chatId: normalized.chatId,
    userKey: normalized.userKey,
    msg: normalized.msg,
    callbackQueryId: normalized.callbackQueryId,
    session: savedSession
  }
}];
